/** PKCE + token primitives shared by every entrypoint (client, native, desktop, server, broker). */
export class Pkce {
  /**
   * JWT claim carrying the S256 challenge from the broker mint to the app-server verify. The check
   * fails open (no claim → no PKCE), so both sides must share this constant — a drifted literal
   * would silently stop binding native/desktop tokens.
   */
  static CLAIM = "pkce_s256";

  static base64url(bytes: Uint8Array) {
    const binary = Array.from(bytes, (byte) => String.fromCharCode(byte)).join("");
    return Pkce.fromBase64(btoa(binary));
  }

  /** For runtimes whose digest APIs return standard base64 (expo-crypto's digestStringAsync). */
  static fromBase64(base64: string) {
    // '=' only ever appears as trailing padding in base64, so everything from the first one goes.
    const unpadded = base64.replaceAll("+", "-").replaceAll("/", "_");
    const padIndex = unpadded.indexOf("=");
    return padIndex === -1 ? unpadded : unpadded.slice(0, padIndex);
  }

  /** 256-bit random value, base64url — used for the CSRF nonce and the PKCE verifier. */
  static randomToken() {
    const bytes = new Uint8Array(32);
    crypto.getRandomValues(bytes);
    return Pkce.base64url(bytes);
  }

  /**
   * S256 PKCE challenge: base64url(SHA-256(verifier)). Uses `crypto.subtle`, which exists on the
   * server (Node 20+/Bun) and in browser/Electron renderers — but not in Hermes, so the native
   * client derives its challenge via expo-crypto instead.
   */
  static async challengeS256(verifier: string) {
    const digest = await crypto.subtle.digest("SHA-256", new TextEncoder().encode(verifier));
    return Pkce.base64url(new Uint8Array(digest));
  }
}
